function fillLanguage(base: Dictionary, overrides: Partial<Dictionary>): Dictionary {
  const merged = { ...T.en, ...base, ...overrides } as Dictionary;
  return merged;
}

for (const language of Object.keys(T) as LanguageCode[]) {
  if (language === "en" || language === "hi" || language === "mr" || language === "gu" || language === "bn" || language === "te" || language === "ta") continue;
  T[language] = fillLanguage({}, compact[language] ?? {});
}


