// All citizen-facing fixed strings are available through this context. Dynamic citizen-entered text
// is intentionally never translated or changed.
type Value = {
  language: LanguageCode;
  setLanguage: (value: LanguageCode) => void;
  t: (key: string) => string;
  categoryLabel: (category: string | null | undefined) => string;
  statusLabel: (status: string | null | undefined) => string;
};

const Context = createContext<Value | null>(null);

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<LanguageCode>(() => {
    const stored = localStorage.getItem("civicfix_language") as LanguageCode | null;
    return stored && LANGUAGES.some((item) => item.code === stored)
      ? stored
      : "en";
  });

  const setLanguage = (value: LanguageCode) => {
    setLanguageState(value);
    localStorage.setItem("civicfix_language", value);
    document.documentElement.lang = value;
  };

  const t = (key: string) => T[language]?.[key] ?? T.en[key] ?? key;

  const categoryLabel = (category: string | null | undefined) => {
    if (!category) return "";
    const key =
      category === "pothole" ? "cat.pothole" :
      category === "drainage" ? "cat.drainage" :
      category === "garbage" ? "cat.garbage" :
      category === "streetlight" ? "cat.streetlight" :
      category === "water_supply" ? "cat.water" :
      category === "road_infrastructure" ? "cat.road" :
      "cat.road";
    return t(key);
  };

  const statusLabel = (status: string | null | undefined) => {
    if (!status) return "";
    return t(`status.${status}`);
  };

  const value = useMemo(
    () => ({ language, setLanguage, t, categoryLabel, statusLabel }),
    [language],
  );

  return (
    <Context.Provider value={value}>
      {children}
    </Context.Provider>
  );
}

export function useLanguage() {
  const value = useContext(Context);
  if (!value) {
    throw new Error("useLanguage must be used inside LanguageProvider");
  }
  return value;
}

export function LanguageSelect({ className = "" }: { className?: string }) {
  const { language, setLanguage, t } = useLanguage();

  return (
    <label className={`language-control ${className}`}>
      <span>{t("nav.language")}</span>
      <select
        value={language}
        onChange={(event) =>
          setLanguage(
            event.target.value as LanguageCode,
          )
        }
        aria-label={t("nav.language")}
      >
        {LANGUAGES.map((item) => (
          <option
            key={item.code}
            value={item.code}
          >
            {item.label}
          </option>
        ))}
      </select>
    </label>
  );
}

